func StartWorker(ctx context.Context, jobs <-chan Job) {
    go func() {
        for {
            select {
            case <-ctx.Done():
                // Graceful shutdown when context is cancelled
                return
            case job, ok := <-jobs:
                if !ok {
                    // Channel closed, exit cleanly
                    return
                }
                process(job)
            }
        }
    }()
}

func merge(ch1, ch2 <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for {
            select {
            case v := <-ch1:  // If ch1 is nil, blocks forever!
                out <- v
            case v := <-ch2:
                out <- v
            }
        }
    }()
    return out
}

func merge(ch1, ch2 <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for ch1 != nil || ch2 != nil {
            select {
            case v, ok := <-ch1:
                if !ok {
                    ch1 = nil  // Disable this case
                    continue
                }
                out <- v
            case v, ok := <-ch2:
                if !ok {
                    ch2 = nil  // Disable this case
                    continue
                }
                out <- v
            }
        }
    }()
    return out
}

